$department=strtolower($student_profile['department']);$education_level=str_contains($department,'higher')||str_contains($department,'college')?'highered':(str_contains($department,'senior')?'seniorhigh':(str_contains($department,'elementary')?'elementary':(str_contains($department,'kinder')?'kinder':'highschool')));
