}
$_SESSION['pds_editor_csrf']=$_SESSION['pds_editor_csrf']??bin2hex(random_bytes(32));
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
    try{
        if(empty($_POST)&&!empty($_SERVER['CONTENT_LENGTH']))throw new RuntimeException('The form or uploads are too large. Reduce the image sizes and try again.');
        if(!is_string($_POST['_pds_csrf']??null)||!hash_equals($_SESSION['pds_editor_csrf'],$_POST['_pds_csrf']))throw new RuntimeException('Your form session expired. Reload the page before saving.');
        if(!is_string($_POST['_pds_revision']??null))throw new RuntimeException('Reload the PDS form before saving.');
        if(($_POST['_pds_complete']??'')!=='1')throw new RuntimeException('The form was not received completely. Reduce the number of rows or uploaded file sizes and try again.');
        $state=$store->save($uid,$education_level,$_POST,$_FILES,$_POST['_pds_revision']);
        $_SESSION['pds_editor_success']='Personal data sheet saved successfully.';
        $savedStep=max(0,min(5,(int)($_POST['_pds_step']??0)));$savedURL=$in_layout?'layout.php?page=fill_pds&pds_step='.$savedStep:'fill_pds.php?pds_step='.$savedStep;
        header('Location: '.$savedURL);exit;
