    catch(InvalidArgumentException|RuntimeException $e){$error_message=$e->getMessage();}
    catch(Throwable $e){error_log('PDS save: '.$e->getMessage());$error_message='The PDS could not be saved. Your previous information is unchanged. Please try again.';}
}
